async () => {
  const w = document.querySelector('iframe').contentWindow;
  const app = w.pc.Application.getApplication();
  const pid = 'Tricot-sink-cabinet-b8lt49nlm';
  const tree = () => { const out = []; app.root.forEach((e) => { if (e.name === 'Tricot_Sink_Point' && e.enabled) out.push(e.children.map((c) => c.name + (c.enabled ? '' : '(off)'))); }); return out; };
  const before = { tree: tree(), cfg: (await w.ConfiguratorAPI.getConfig(pid))?.sinkType ?? null };
  const res = await w.ConfiguratorAPI.setConfig(pid, { sinkType: 'Vessel' });
  await new Promise((r) => setTimeout(r, 2500));
  const c = await w.ConfiguratorAPI.getConfig(pid);
  return { before, setConfigResult: JSON.parse(JSON.stringify(res ?? null)), after: { tree: tree(), sinkType: (c?.config ?? c)?.sinkType, VesselColor: (c?.config ?? c)?.VesselColor } };
}
